# Log actions that move a document or change who holds it; an expedite
# request or similar note after a return doesn't mean it was fixed.
MOVEMENT_ACTIONS = [
    'created', 'released', 'received', 'returned', 'released_to_citizen', 'released_to_origin',
    'flagged_missing', 'return_initiated', 'return_received', 'citizen_return_initiated',
]


def mark_returned(apps, schema_editor):
    """Documents sitting at an office because they were sent back there are now 'Returned'."""
    Document = apps.get_model('documents', 'Document')
    DocumentLog = apps.get_model('documents', 'DocumentLog')
    for document in Document.objects.filter(status='in_progress'):
        last = (
            DocumentLog.objects.filter(document=document, action__in=MOVEMENT_ACTIONS)
            .order_by('-timestamp', '-id').first()
        )
        if last and last.action == 'return_received':
            Document.objects.filter(pk=document.pk).update(status='returned')


def unmark_returned(apps, schema_editor):
    Document = apps.get_model('documents', 'Document')
    Document.objects.filter(status='returned').update(status='in_progress')


